int is_sorted(int a[], int n) {
    for (int i = 0; i < n - 1; i++) {
        if (a[i] > a[i + 1]) {
            return 0;
        }
    }
    return 1;
}

int is_sorted(int a[], int n) {
    int i = 0;
    while (i < n - 1) {
        if (a[i] > a[i + 1]) return 0;
        i++;
    }
    return 1;
}

